"""Offline QUIC v1 trace auditor (finite synthetic model)."""
import sys
import json

MAX = 4611686018427387903
LEVELS = ("I", "H", "Z", "A")
MAX_TIME = 1000000000000
MAX_DATA_BYTES = 2 * 1024 * 1024


class InvalidInput(Exception):
    pass


class SemErr(Exception):
    def __init__(self, code, frame):
        self.code = code
        self.frame = frame


# ---------------------------------------------------------------------------
# JSON parsing with strict validation hooks
# ---------------------------------------------------------------------------

def _no_dup(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise InvalidInput()
        d[k] = v
    return d


def _reject_float(x):
    raise InvalidInput()


def _reject_const(x):
    raise InvalidInput()


def parse_json(raw):
    try:
        s = raw.decode("utf-8")
    except Exception:
        raise InvalidInput()
    try:
        return json.loads(
            s,
            object_pairs_hook=_no_dup,
            parse_float=_reject_float,
            parse_constant=_reject_const,
        )
    except InvalidInput:
        raise
    except Exception:
        raise InvalidInput()


# ---------------------------------------------------------------------------
# Validation
# ---------------------------------------------------------------------------

def is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def is_bool(x):
    return isinstance(x, bool)


def check_int(x, lo, hi):
    if not is_int(x) or x < lo or x > hi:
        raise InvalidInput()
    return x


class Counter:
    def __init__(self):
        self.events = 0
        self.packets = 0
        self.frames = 0
        self.data = 0


HEXCHARS = set("0123456789abcdef")


def validate_hex(h, counter):
    if not isinstance(h, str):
        raise InvalidInput()
    if len(h) % 2 != 0:
        raise InvalidInput()
    if len(h) > 2048 * 2:
        raise InvalidInput()
    for c in h:
        if c not in HEXCHARS:
            raise InvalidInput()
    counter.data += len(h) // 2
    if counter.data > MAX_DATA_BYTES:
        raise InvalidInput()
    return h


def validate_config_ranges(r):
    if not isinstance(r, list):
        raise InvalidInput()
    if len(r) > 32:
        raise InvalidInput()
    prev_high = None
    for pair in r:
        if not isinstance(pair, list) or len(pair) != 2:
            raise InvalidInput()
        lo = pair[0]
        hi = pair[1]
        check_int(lo, 0, MAX)
        check_int(hi, 0, MAX)
        if lo > hi:
            raise InvalidInput()
        if prev_high is not None:
            if lo <= prev_high + 1:
                raise InvalidInput()
        prev_high = hi
    return r


def validate_frame_ranges(r):
    # Same endpoint/length domains as CONFIG ranges but ordering problems are
    # protocol errors, not input errors.
    if not isinstance(r, list):
        raise InvalidInput()
    if len(r) > 32:
        raise InvalidInput()
    for pair in r:
        if not isinstance(pair, list) or len(pair) != 2:
            raise InvalidInput()
        check_int(pair[0], 0, MAX)
        check_int(pair[1], 0, MAX)
    return r


FRAME_KEY_SETS = {
    "PADDING": {"type"},
    "PING": {"type"},
    "ACK": {"type", "ranges"},
    "CRYPTO": {"type", "offset", "data_hex"},
    "STREAM": {"type", "id", "offset", "data_hex", "fin"},
    "RESET_STREAM": {"type", "id", "final_size"},
    "STOP_SENDING": {"type", "id"},
    "CLOSE": {"type", "app", "code"},
    "HANDSHAKE_DONE": {"type"},
    "UNKNOWN": {"type"},
}


def validate_frame(f, counter):
    if not isinstance(f, dict):
        raise InvalidInput()
    if "type" not in f:
        raise InvalidInput()
    t = f["type"]
    if not isinstance(t, str) or t not in FRAME_KEY_SETS:
        raise InvalidInput()
    if set(f.keys()) != FRAME_KEY_SETS[t]:
        raise InvalidInput()
    counter.frames += 1
    if counter.frames > 60000:
        raise InvalidInput()
    if t in ("PADDING", "PING", "HANDSHAKE_DONE", "UNKNOWN"):
        return
    if t == "ACK":
        validate_frame_ranges(f["ranges"])
    elif t == "CRYPTO":
        check_int(f["offset"], 0, MAX)
        validate_hex(f["data_hex"], counter)
    elif t == "STREAM":
        check_int(f["id"], 0, MAX)
        check_int(f["offset"], 0, MAX)
        if not is_bool(f["fin"]):
            raise InvalidInput()
        validate_hex(f["data_hex"], counter)
    elif t == "RESET_STREAM":
        check_int(f["id"], 0, MAX)
        check_int(f["final_size"], 0, MAX)
    elif t == "STOP_SENDING":
        check_int(f["id"], 0, MAX)
    elif t == "CLOSE":
        if not is_bool(f["app"]):
            raise InvalidInput()
        check_int(f["code"], 0, MAX)


def validate_packet(p, counter):
    if not isinstance(p, dict):
        raise InvalidInput()
    if set(p.keys()) != {"level", "pn", "auth", "frames"}:
        raise InvalidInput()
    if not isinstance(p["level"], str) or p["level"] not in LEVELS:
        raise InvalidInput()
    check_int(p["pn"], 0, MAX)
    if not is_bool(p["auth"]):
        raise InvalidInput()
    frames = p["frames"]
    if not isinstance(frames, list) or len(frames) > 64:
        raise InvalidInput()
    counter.packets += 1
    if counter.packets > 20000:
        raise InvalidInput()
    for f in frames:
        validate_frame(f, counter)


def validate_event(e, prev_t, counter):
    if not isinstance(e, dict):
        raise InvalidInput()
    if "t" not in e or "op" not in e:
        raise InvalidInput()
    t = e["t"]
    check_int(t, 0, MAX_TIME)
    if t < prev_t:
        raise InvalidInput()
    op = e["op"]
    if not isinstance(op, str):
        raise InvalidInput()
    if op == "key":
        if set(e.keys()) != {"t", "op", "level", "action"}:
            raise InvalidInput()
        if not isinstance(e["level"], str) or e["level"] not in LEVELS:
            raise InvalidInput()
        if not isinstance(e["action"], str) or e["action"] not in ("install", "discard"):
            raise InvalidInput()
    elif op == "tick":
        if set(e.keys()) != {"t", "op"}:
            raise InvalidInput()
    elif op == "datagram":
        if set(e.keys()) != {"t", "op", "bytes", "packets"}:
            raise InvalidInput()
        check_int(e["bytes"], 0, 65535)
        packets = e["packets"]
        if not isinstance(packets, list) or len(packets) < 1 or len(packets) > 16:
            raise InvalidInput()
        for p in packets:
            validate_packet(p, counter)
    else:
        raise InvalidInput()
    return t


def validate_config(c):
    if not isinstance(c, dict):
        raise InvalidInput()
    expected = {
        "early", "overlap", "buffer_packets", "idle_ms", "max_streams_bidi",
        "max_streams_uni", "max_stream_data", "max_data", "crypto_limit", "sent",
    }
    if set(c.keys()) != expected:
        raise InvalidInput()
    if not is_bool(c["early"]):
        raise InvalidInput()
    if not isinstance(c["overlap"], str) or c["overlap"] not in ("reject", "first"):
        raise InvalidInput()
    check_int(c["buffer_packets"], 0, 1024)
    check_int(c["idle_ms"], 0, 1000000000)
    check_int(c["max_streams_bidi"], 0, 1024)
    check_int(c["max_streams_uni"], 0, 1024)
    check_int(c["max_stream_data"], 0, 65536)
    check_int(c["max_data"], 0, MAX)
    check_int(c["crypto_limit"], 0, 65536)
    sent = c["sent"]
    if not isinstance(sent, dict) or set(sent.keys()) != {"I", "H", "A"}:
        raise InvalidInput()
    for k in ("I", "H", "A"):
        validate_config_ranges(sent[k])
    return c


def validate_request(obj):
    if not isinstance(obj, dict):
        raise InvalidInput()
    if set(obj.keys()) != {"version", "traces"}:
        raise InvalidInput()
    if not is_int(obj["version"]) or obj["version"] != 1:
        raise InvalidInput()
    traces = obj["traces"]
    if not isinstance(traces, list):
        raise InvalidInput()
    if len(traces) > 32:
        raise InvalidInput()
    counter = Counter()
    ids = set()
    for tr in traces:
        if not isinstance(tr, dict):
            raise InvalidInput()
        if set(tr.keys()) != {"id", "config", "events"}:
            raise InvalidInput()
        tid = tr["id"]
        if not isinstance(tid, str) or not (1 <= len(tid) <= 32):
            raise InvalidInput()
        for ch in tid:
            if not (ch.isascii() and (ch.isalnum() or ch in "_-")):
                raise InvalidInput()
        if tid in ids:
            raise InvalidInput()
        ids.add(tid)
        validate_config(tr["config"])
        events = tr["events"]
        if not isinstance(events, list):
            raise InvalidInput()
        prev_t = -1
        for e in events:
            counter.events += 1
            if counter.events > 20000:
                raise InvalidInput()
            prev_t = validate_event(e, prev_t, counter)
    return obj


# ---------------------------------------------------------------------------
# Replay
# ---------------------------------------------------------------------------

class Stream:
    __slots__ = ("highest", "final_size", "reset", "stopped", "bytes")

    def __init__(self):
        self.highest = 0
        self.final_size = None
        self.reset = False
        self.stopped = False
        self.bytes = {}


class Crypto:
    __slots__ = ("highest", "bytes")

    def __init__(self):
        self.highest = 0
        self.bytes = {}


class Pending:
    __slots__ = ("event", "packet", "packet_obj", "level", "arrival_t")

    def __init__(self, event, packet, packet_obj, level, arrival_t):
        self.event = event
        self.packet = packet
        self.packet_obj = packet_obj
        self.level = level
        self.arrival_t = arrival_t


PERMIT = {
    "PADDING": {"I", "H", "Z", "A"},
    "PING": {"I", "H", "Z", "A"},
    "ACK": {"I", "H", "A"},
    "CRYPTO": {"I", "H", "A"},
    "STREAM": {"Z", "A"},
    "RESET_STREAM": {"Z", "A"},
    "STOP_SENDING": {"Z", "A"},
    "HANDSHAKE_DONE": set(),
}


def frame_permitted(level, fr):
    t = fr["type"]
    if t == "CLOSE":
        if fr["app"]:
            return level in ("Z", "A")
        return level in ("I", "H", "Z", "A")
    return level in PERMIT[t]


class Replay:
    def __init__(self, trace):
        self.id = trace["id"]
        self.cfg = trace["config"]
        self.events = trace["events"]
        early = self.cfg["early"]
        self.keys = {
            "I": "live",
            "H": "absent",
            "Z": "live" if early else "absent",
            "A": "absent",
        }
        self.pn_seen = {"I": set(), "H": set(), "App": set()}
        self.streams = {}
        self.crypto = {"I": Crypto(), "H": Crypto(), "A": Crypto()}
        self.received_total = 0
        self.last_activity = 0
        self.conn = {
            "state": "open",
            "code": None,
            "at_ms": None,
            "source": None,
            "peer_code": None,
        }
        self.queue = []
        self.results = {}

    # -- result recording ---------------------------------------------------
    def set_result(self, event, packet, status, reason, at_ms, frame):
        self.results[(event, packet)] = {
            "event": event,
            "packet": packet,
            "status": status,
            "reason": reason,
            "at_ms": at_ms,
            "frame": frame,
        }

    # -- journalized mutations ---------------------------------------------
    def get_stream(self, sid, journal):
        s = self.streams.get(sid)
        if s is None:
            s = Stream()
            self.streams[sid] = s
            journal.append(("snew", sid))
        return s

    def set_field(self, journal, obj, field, value):
        old = getattr(obj, field)
        if old != value:
            journal.append(("sfield", obj, field, old))
            setattr(obj, field, value)

    def add_total(self, journal, delta):
        if delta:
            journal.append(("rtotal", self.received_total))
            self.received_total += delta

    def set_highest(self, journal, stream, newh):
        old = stream.highest
        if newh != old:
            journal.append(("sfield", stream, "highest", old))
            stream.highest = newh
            self.add_total(journal, newh - old)

    def store_bytes(self, journal, bytedict, offset, data, frame):
        policy = self.cfg["overlap"]
        for i, b in enumerate(data):
            off = offset + i
            ex = bytedict.get(off)
            if ex is None:
                bytedict[off] = b
                journal.append(("byte", bytedict, off))
            else:
                if ex == b:
                    continue
                if policy == "reject":
                    raise SemErr("PROTOCOL_VIOLATION", frame)
                # first: keep earlier stored byte
                continue

    def rollback(self, journal):
        for entry in reversed(journal):
            tag = entry[0]
            if tag == "sfield":
                setattr(entry[1], entry[2], entry[3])
            elif tag == "snew":
                del self.streams[entry[1]]
            elif tag == "rtotal":
                self.received_total = entry[1]
            elif tag == "byte":
                del entry[1][entry[2]]
            elif tag == "cfield":
                setattr(entry[1], entry[2], entry[3])

    # -- termination --------------------------------------------------------
    def terminate(self, state, code, at_ms, source, peer_code):
        self.conn["state"] = state
        self.conn["code"] = code
        self.conn["at_ms"] = at_ms
        self.conn["source"] = source
        self.conn["peer_code"] = peer_code
        for pending in self.queue:
            self.set_result(pending.event, pending.packet, "dropped",
                            "CONNECTION_CLOSED", at_ms, None)
        self.queue = []

    def error_terminate(self, ei, pi, frame, code, t):
        self.set_result(ei, pi, "error", code, t, frame)
        self.terminate("closed", code, t, {"event": ei, "packet": pi, "frame": frame}, None)

    # -- semantic frame handlers -------------------------------------------
    def do_ack(self, lvl, fi, fr):
        ranges = fr["ranges"]
        if len(ranges) == 0:
            raise SemErr("FRAME_ENCODING_ERROR", fi)
        prev_high = None
        for pair in ranges:
            lo, hi = pair[0], pair[1]
            if lo > hi:
                raise SemErr("FRAME_ENCODING_ERROR", fi)
            if prev_high is not None and lo <= prev_high + 1:
                raise SemErr("FRAME_ENCODING_ERROR", fi)
            prev_high = hi
        sent = self.cfg["sent"][lvl]
        for pair in ranges:
            lo, hi = pair[0], pair[1]
            covered = False
            for s in sent:
                if s[0] <= lo and hi <= s[1]:
                    covered = True
                    break
            if not covered:
                raise SemErr("PROTOCOL_VIOLATION", fi)

    def do_crypto(self, lvl, fi, fr, journal):
        offset = fr["offset"]
        data = bytes.fromhex(fr["data_hex"])
        end = offset + len(data)
        if end > MAX:
            raise SemErr("FRAME_ENCODING_ERROR", fi)
        if end > self.cfg["crypto_limit"]:
            raise SemErr("CRYPTO_BUFFER_EXCEEDED", fi)
        c = self.crypto[lvl]
        self.store_bytes(journal, c.bytes, offset, data, fi)
        if end > c.highest:
            journal.append(("cfield", c, "highest", c.highest))
            c.highest = end

    def do_stream(self, fi, fr, journal):
        sid = fr["id"]
        offset = fr["offset"]
        data = bytes.fromhex(fr["data_hex"])
        fin = fr["fin"]
        r = sid % 4
        if r not in (0, 2):
            raise SemErr("STREAM_STATE_ERROR", fi)
        limit = self.cfg["max_streams_bidi"] if r == 0 else self.cfg["max_streams_uni"]
        if sid // 4 + 1 > limit:
            raise SemErr("STREAM_LIMIT_ERROR", fi)
        s = self.get_stream(sid, journal)
        end = offset + len(data)
        if end > MAX:
            raise SemErr("FRAME_ENCODING_ERROR", fi)
        fs = s.final_size
        if fs is not None and (end > fs or (fin and end != fs)):
            raise SemErr("FINAL_SIZE_ERROR", fi)
        if fin and end < s.highest:
            raise SemErr("FINAL_SIZE_ERROR", fi)
        if end > self.cfg["max_stream_data"]:
            raise SemErr("FLOW_CONTROL_ERROR", fi)
        newh = s.highest if s.highest >= end else end
        delta = newh - s.highest
        if self.received_total + delta > self.cfg["max_data"]:
            raise SemErr("FLOW_CONTROL_ERROR", fi)
        if not s.reset:
            self.store_bytes(journal, s.bytes, offset, data, fi)
        self.set_highest(journal, s, newh)
        if fin:
            self.set_field(journal, s, "final_size", end)

    def do_reset(self, fi, fr, journal):
        sid = fr["id"]
        fs_new = fr["final_size"]
        r = sid % 4
        if r not in (0, 2):
            raise SemErr("STREAM_STATE_ERROR", fi)
        limit = self.cfg["max_streams_bidi"] if r == 0 else self.cfg["max_streams_uni"]
        if sid // 4 + 1 > limit:
            raise SemErr("STREAM_LIMIT_ERROR", fi)
        s = self.get_stream(sid, journal)
        if s.final_size is not None and fs_new != s.final_size:
            raise SemErr("FINAL_SIZE_ERROR", fi)
        if fs_new < s.highest:
            raise SemErr("FINAL_SIZE_ERROR", fi)
        if fs_new > self.cfg["max_stream_data"]:
            raise SemErr("FLOW_CONTROL_ERROR", fi)
        newh = s.highest if s.highest >= fs_new else fs_new
        delta = newh - s.highest
        if self.received_total + delta > self.cfg["max_data"]:
            raise SemErr("FLOW_CONTROL_ERROR", fi)
        self.set_highest(journal, s, newh)
        self.set_field(journal, s, "final_size", fs_new)
        self.set_field(journal, s, "reset", True)

    def do_stop(self, fi, fr, journal):
        sid = fr["id"]
        r = sid % 4
        if r != 0:
            raise SemErr("STREAM_STATE_ERROR", fi)
        if sid // 4 + 1 > self.cfg["max_streams_bidi"]:
            raise SemErr("STREAM_LIMIT_ERROR", fi)
        s = self.get_stream(sid, journal)
        self.set_field(journal, s, "stopped", True)

    def apply_frames(self, lvl, fi_start, frames, journal):
        for idx, fr in enumerate(frames):
            fi = fi_start + idx
            t = fr["type"]
            if t == "PADDING" or t == "PING":
                continue
            elif t == "ACK":
                self.do_ack(lvl, fi, fr)
            elif t == "CRYPTO":
                self.do_crypto(lvl, fi, fr, journal)
            elif t == "STREAM":
                self.do_stream(fi, fr, journal)
            elif t == "RESET_STREAM":
                self.do_reset(fi, fr, journal)
            elif t == "STOP_SENDING":
                self.do_stop(fi, fr, journal)
            elif t == "CLOSE":
                code = "PEER_APPLICATION_CLOSE" if fr["app"] else "PEER_TRANSPORT_CLOSE"
                return (code, fr["code"], fi)
        return None

    # -- packet processing --------------------------------------------------
    def process_live(self, ei, pi, pkt, t):
        lvl = pkt["level"]
        if not pkt["auth"]:
            self.set_result(ei, pi, "dropped", "AUTH", t, None)
            return
        if lvl == "I":
            space = "I"
        elif lvl == "H":
            space = "H"
        else:
            space = "App"
        pn = pkt["pn"]
        if pn in self.pn_seen[space]:
            self.set_result(ei, pi, "duplicate", "DUPLICATE", t, None)
            return
        frames = pkt["frames"]
        if len(frames) == 0:
            self.error_terminate(ei, pi, None, "FRAME_ENCODING_ERROR", t)
            return
        for idx, fr in enumerate(frames):
            if fr["type"] == "UNKNOWN":
                self.error_terminate(ei, pi, idx, "FRAME_ENCODING_ERROR", t)
                return
            if not frame_permitted(lvl, fr):
                self.error_terminate(ei, pi, idx, "PROTOCOL_VIOLATION", t)
                return
        journal = []
        try:
            close_info = self.apply_frames(lvl, 0, frames, journal)
        except SemErr as e:
            self.rollback(journal)
            self.error_terminate(ei, pi, e.frame, e.code, t)
            return
        # success commit
        self.pn_seen[space].add(pn)
        self.last_activity = t
        self.set_result(ei, pi, "accepted", "OK", t, None)
        if close_info is not None:
            code, peer, fi = close_info
            self.terminate("closed", code, t,
                           {"event": ei, "packet": pi, "frame": fi}, peer)

    # -- datagram / key / event --------------------------------------------
    def handle_datagram(self, ei, ev):
        t = ev["t"]
        packets = ev["packets"]
        size = ev["bytes"]
        if self.conn["state"] != "open":
            for pi in range(len(packets)):
                self.set_result(ei, pi, "dropped", "CONNECTION_CLOSED", t, None)
            return
        # layout check: A packet not final => drop all
        for pi in range(len(packets) - 1):
            if packets[pi]["level"] == "A":
                for pj in range(len(packets)):
                    self.set_result(ei, pj, "dropped", "LAYOUT", t, None)
                return
        for pi, pkt in enumerate(packets):
            if self.conn["state"] != "open":
                self.set_result(ei, pi, "dropped", "CONNECTION_CLOSED", t, None)
                continue
            lvl = pkt["level"]
            if lvl == "I" and size < 1200:
                self.set_result(ei, pi, "dropped", "INITIAL_TOO_SMALL", t, None)
                continue
            if lvl == "Z" and not self.cfg["early"]:
                self.set_result(ei, pi, "dropped", "EARLY_REJECTED", t, None)
                continue
            ks = self.keys[lvl]
            if ks == "discarded":
                self.set_result(ei, pi, "dropped", "KEYS_DISCARDED", t, None)
                continue
            if ks == "absent":
                if len(self.queue) < self.cfg["buffer_packets"]:
                    self.queue.append(Pending(ei, pi, pkt, lvl, t))
                else:
                    self.set_result(ei, pi, "dropped", "BUFFER_FULL", t, None)
                continue
            self.process_live(ei, pi, pkt, t)

    def drain(self, lvl, t):
        while True:
            idx = -1
            for i, p in enumerate(self.queue):
                if p.level == lvl:
                    idx = i
                    break
            if idx < 0:
                return
            pending = self.queue.pop(idx)
            if self.conn["state"] != "open":
                at = self.conn["at_ms"]
                if at is None:
                    at = t
                self.set_result(pending.event, pending.packet, "dropped",
                                "CONNECTION_CLOSED", at, None)
                continue
            self.process_live(pending.event, pending.packet, pending.packet_obj, t)

    def handle_key(self, ei, ev):
        lvl = ev["level"]
        act = ev["action"]
        t = ev["t"]
        if act == "install":
            if self.keys[lvl] == "absent":
                self.keys[lvl] = "live"
                self.drain(lvl, t)
            # live or discarded: no-op
        else:  # discard
            if self.keys[lvl] != "discarded":
                self.keys[lvl] = "discarded"
                remaining = []
                for pending in self.queue:
                    if pending.level == lvl:
                        self.set_result(pending.event, pending.packet, "dropped",
                                        "KEYS_DISCARDED", t, None)
                    else:
                        remaining.append(pending)
                self.queue = remaining

    def handle_event(self, ei, ev):
        t = ev["t"]
        # idle timer check at beginning of each event
        if self.conn["state"] == "open" and self.cfg["idle_ms"] != 0:
            deadline = self.last_activity + self.cfg["idle_ms"]
            if t >= deadline:
                self.terminate("idle", "IDLE_TIMEOUT", deadline,
                               {"event": ei, "packet": None, "frame": None}, None)
        op = ev["op"]
        if op == "key":
            if self.conn["state"] != "open":
                return
            self.handle_key(ei, ev)
        elif op == "tick":
            return
        else:  # datagram
            self.handle_datagram(ei, ev)

    # -- run and output -----------------------------------------------------
    def contiguous_hex(self, bytedict):
        if not bytedict:
            return ""
        out = bytearray()
        pos = 0
        while pos in bytedict:
            out.append(bytedict[pos])
            pos += 1
        return out.hex()

    def run(self):
        for ei, ev in enumerate(self.events):
            self.handle_event(ei, ev)
        # EOF: pending remain buffered
        for pending in self.queue:
            self.set_result(pending.event, pending.packet, "buffered",
                            "NO_KEYS", pending.arrival_t, None)
        self.queue = []
        packets_out = [self.results[k] for k in sorted(self.results)]
        streams_out = []
        for sid in sorted(self.streams):
            s = self.streams[sid]
            streams_out.append({
                "id": sid,
                "highest": s.highest,
                "final_size": s.final_size,
                "reset": s.reset,
                "stopped": s.stopped,
                "delivered_hex": self.contiguous_hex(s.bytes),
            })
        crypto_out = []
        for lvl in ("I", "H", "A"):
            c = self.crypto[lvl]
            crypto_out.append({
                "level": lvl,
                "highest": c.highest,
                "contiguous_hex": self.contiguous_hex(c.bytes),
            })
        conn = self.conn
        connection = {
            "state": conn["state"],
            "code": conn["code"],
            "at_ms": conn["at_ms"],
            "source": conn["source"],
            "peer_code": conn["peer_code"],
            "last_activity_ms": self.last_activity,
        }
        return {
            "id": self.id,
            "packets": packets_out,
            "connection": connection,
            "keys": {
                "I": self.keys["I"],
                "H": self.keys["H"],
                "Z": self.keys["Z"],
                "A": self.keys["A"],
            },
            "received_total": self.received_total,
            "streams": streams_out,
            "crypto": crypto_out,
        }


def main():
    raw = sys.stdin.buffer.read()
    try:
        if len(raw) > 16 * 1024 * 1024:
            raise InvalidInput()
        obj = parse_json(raw)
        validate_request(obj)
        results = [Replay(tr).run() for tr in obj["traces"]]
        out = {"version": 1, "results": results}
    except InvalidInput:
        sys.stdout.write(json.dumps({"error": "INVALID_INPUT"}))
        return
    except Exception:
        import traceback
        traceback.print_exc(file=sys.stderr)
        sys.stdout.write(json.dumps({"error": "INVALID_INPUT"}))
        return
    sys.stdout.write(json.dumps(out))


if __name__ == "__main__":
    main()
